INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-01','Open-Loop vs Closed-Loop Control','Easy','EEE','arena','compare','Control Systems','multiple_choice','A washing machine with a fixed 30-minute cycle regardless of load size is an example of:','{"choices": ["Closed-loop control", "Adaptive control", "Feedback control", "Open-loop control"], "correct": 3}'::jsonb,'Open-loop: output is not measured and fed back to correct the input. No correction for disturbances. Closed-loop (feedback): sensor measures output, compares to setpoint, corrects error. Open-loop is simpler but inaccurate; closed-loop is accurate but complex.','{multiple_choice}'::text[],0.88) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-02','PID Controller: Proportional Action','Easy','EEE','arena','predict','Control Systems','multiple_choice','In a PID controller, increasing proportional gain K_P:','{"choices": ["Eliminates steady-state error", "Reduces overshoot", "Increases response speed but may increase overshoot and reduce stability margin", "Has no effect on dynamic response"], "correct": 2}'::jsonb,'Proportional action: u(t) = K_P × e(t). Higher K_P → faster response to error → but also amplifies noise and can cause oscillation. Steady-state error is reduced but not eliminated by P alone (requires integral term). P control creates offset for most systems.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-03','First-Order System Step Response','Easy','EEE','arena','calculate','Control Systems','multiple_choice','A first-order system has time constant τ = 2 s. After one time constant (t = 2 s) following a step input, the output reaches what percentage of final value?','{"choices": ["50%", "99%", "86.5%", "63.2%"], "correct": 3}'::jsonb,'First-order step response: y(t) = Y_final × (1 − e^(−t/τ)). At t = τ: y = Y(1 − e⁻¹) = Y × 0.632 = 63.2%. At t = 2τ: 86.5%. At t = 5τ: 99.3% (considered settled).','{multiple_choice}'::text[],0.87) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-04','Steady-State Error: Type 0 System','Easy','EEE','arena','predict','Control Systems','multiple_choice','A unity-feedback control system with open-loop gain K = 10 (Type 0 — no integrators in open loop). For a unit step reference input, the steady-state error is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-05','Routh-Hurwitz Stability Criterion','Easy','EEE','arena','select','Control Systems','multiple_choice','The Routh-Hurwitz criterion determines system stability by:','{"choices": ["Finding the exact roots of the characteristic equation", "Plotting the system''s frequency response", "Examining the signs of elements in the first column of the Routh array — if all positive, system is stable (all poles in LHP)", "Computing the step response settling time"], "correct": 2}'::jsonb,'Routh-Hurwitz: construct array from characteristic polynomial coefficients. Number of sign changes in first column = number of roots with positive real part (RHP poles). If no sign changes → all poles in LHP → stable. Avoids solving high-degree polynomial.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-06','Transfer Function: DC Motor','Medium','EEE','arena','interpret','Control Systems','multiple_choice','A simplified DC motor transfer function (speed to armature voltage) is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-07','Root Locus: Gain and Stability','Medium','EEE','arena','interpret','Control Systems','multiple_choice','On a root locus plot, as gain K increases from 0 to ∞, poles start at:','{"choices": ["Infinity, moving to open-loop zeros", "Open-loop poles, moving towards open-loop zeros (or to infinity along asymptotes)", "The origin, moving to closed-loop poles", "Open-loop zeros, moving towards poles"], "correct": 1}'::jsonb,'Root locus rules: (1) Starts (K=0) at open-loop poles. (2) Ends (K→∞) at open-loop zeros or along asymptotes to infinity. (3) Number of asymptotes = n−m (poles minus zeros). System stability changes when root locus crosses imaginary axis.','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-08','Integral Windup in PID','Medium','EEE','arena','diagnose','Control Systems','multiple_choice','Integral windup in a PID controller occurs when:','{"choices": ["The derivative term oscillates at high frequency", "The setpoint is reached too quickly", "The actuator saturates (hits its limit) while the integrator continues accumulating error — causing large overshoot and slow recovery when the setpoint changes or saturation ends", "The proportional gain is too low"], "correct": 2}'::jsonb,'Anti-windup techniques: (1) Clamp integrator output to actuator limits. (2) Back-calculation: feedback from actuator output to reduce integral when saturated. (3) Conditional integration: stop integrating when saturated. Essential in motor/valve control systems.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-09','Phase Margin from Bode Plot','Medium','EEE','arena','interpret','Control Systems','multiple_choice','From a Bode plot, the phase margin is found as:','{"choices": ["Phase angle at ω = 0", "Distance from −180° at the gain crossover frequency (where |G(jω)| = 0 dB): PM = 180° + φ(ω_gc)", "The maximum phase shift in the plot", "Phase at the phase crossover frequency"], "correct": 1}'::jsonb,'Gain crossover frequency ω_gc: where magnitude = 0 dB. Phase margin PM = 180° + φ(ω_gc). PM > 0° → stable. For good transient response: PM = 45°–60°. PM < 0° → unstable. PM ≈ 30° → acceptable. Larger PM → better damping.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-10','Ziegler-Nichols Tuning: Ultimate Gain','Medium','EEE','arena','calculate','Control Systems','multiple_choice','Ziegler-Nichols ultimate gain method: the ultimate gain K_u = 200 and ultimate period P_u = 0.5 s. Z-N PID tuning: K_P = 0.6K_u, T_I = P_u/2, T_D = P_u/8.
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-11','State Space Representation','Medium','EEE','arena','interpret','Control Systems','multiple_choice','The state-space representation ẋ = Ax + Bu, y = Cx + Du is preferred over transfer functions for:','{"choices": ["Single-input, single-output systems", "Purely frequency-domain analysis", "MIMO systems, nonlinear systems, and modern control design (LQR, Kalman filter, pole placement) — TF is limited to LTI SISO systems", "Computing Bode plots only"], "correct": 2}'::jsonb,'State space: generalises to MIMO (multiple input, multiple output), nonlinear systems (when linearised), and time-varying systems. Enables modern control: LQR (optimal control), LQE (Kalman filter), pole placement. TF analysis: limited to LTI SISO frequency-domain methods.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-12','Controllability: System Matrix','Hard','EEE','arena','interpret','Control Systems','multiple_choice','A system ẋ = Ax + Bu is controllable if and only if:','{"choices": ["The A matrix has all eigenvalues in the LHP", "The controllability matrix C = [B, AB, A²B, ..., Aⁿ⁻¹B] has full row rank (rank = n)", "The B matrix is square", "All states are directly measured"], "correct": 1}'::jsonb,'Controllability: ability to drive system from any initial state to any final state in finite time. Check: rank(C_c) = n (system order). Uncontrollable modes cannot be influenced by input — some pole placement configurations are impossible for uncontrollable systems.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-13','LQR: Optimal Control Trade-off','Hard','EEE','arena','interpret','Control Systems','multiple_choice','The LQR (Linear Quadratic Regulator) minimises cost J = ∫(x^T Q x + u^T R u) dt. Increasing the R matrix (control effort penalty) results in:','{"choices": ["Faster system response", "More aggressive control", "Slower, more conservative control with smaller control inputs — the controller penalises large actuator efforts, reducing bandwidth and overshoot", "No change in controller gains"], "correct": 2}'::jsonb,'LQR trade-off: Q penalises state deviation (desire fast convergence). R penalises control effort (desire small inputs). High Q/R ratio: aggressive, fast, large inputs. Low Q/R: slow, conservative. LQR guarantees minimum gain margin of 6 dB and phase margin of 60° — inherent robustness.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-14','Kalman Filter: Prediction-Update','Hard','EEE','arena','interpret','Control Systems','multiple_choice','The Kalman filter is described as "optimal" for linear Gaussian systems because:','{"choices": ["It has the smallest code size", "It minimises the mean squared estimation error — the Kalman gain K optimally weights model prediction vs noisy measurement; if process noise is high, it trusts measurements more; if measurement noise is high, it trusts the model more", "It works for nonlinear systems", "It requires no tuning parameters"], "correct": 1}'::jsonb,'Kalman gain: K = P_pred H^T (H P_pred H^T + R)^{−1}. High R (noisy measurements): K → 0 (trust model). High Q (uncertain model): K → large (trust measurements). Tuning: choose Q (process noise covariance) and R (measurement noise covariance) from physical knowledge.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-15','Smith Predictor: Dead Time Compensation','Hard','EEE','arena','select','Control Systems','multiple_choice','A process has significant dead time (transport delay) T_d. A Smith predictor improves control by:','{"choices": ["Reducing dead time by increasing sample rate", "Using a model of the process without dead time inside the inner feedback loop — effectively removing the dead time from the characteristic equation, allowing higher gain and faster control", "Predicting future setpoint changes", "Adding a derivative filter to compensate"], "correct": 1}'::jsonb,'Dead time degrades control: PID gain must be reduced to maintain stability, resulting in slow response. Smith predictor: inner loop controls model (no dead time) → outer loop adds measured dead time. Removes e^{−sT_d} from denominator → can design controller without dead-time limitations.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-16','Model Predictive Control (MPC)','Hard','EEE','arena','select','Control Systems','multiple_choice','Model Predictive Control (MPC) explicitly handles constraints on inputs and states because:','{"choices": ["It uses a lookup table of pre-computed inputs", "At each time step, MPC solves an optimisation problem over a receding horizon — the optimisation explicitly includes constraints (u_min ≤ u ≤ u_max, x_min ≤ x ≤ x_max) and finds the optimal feasible trajectory", "It uses relay control within constraint bounds", "It is a special case of PID with saturation limits"], "correct": 1}'::jsonb,'MPC (receding horizon control): predict N steps ahead using model, optimise sequence of N inputs, apply only first input, repeat. Constraints are explicit in the QP (quadratic programme). Handles MIMO, constraints, and nonlinear systems (NMPC). Industry standard in refining and chemical plants.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-17','Cascade Control Structure','Hard','EEE','arena','interpret','Control Systems','multiple_choice','Cascade control (inner/outer loop) is used when:','{"choices": ["Only one sensor is available", "Two measurements are available and the inner loop variable directly affects the outer loop — the inner (faster) loop rejects disturbances before they propagate to the outer (slower) loop, improving overall disturbance rejection", "The process has no dead time", "Both loops must operate at the same bandwidth"], "correct": 1}'::jsonb,'Example: boiler drum level control. Outer loop: level → setpoint for steam flow. Inner loop: flow control (fast response to flow disturbances). Inner bandwidth must be 5–10× higher than outer. Cascade removes inner disturbances before they upset the outer variable.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-18','Nonlinear Control: Sliding Mode','Hard','EEE','arena','interpret','Control Systems','multiple_choice','Sliding mode control (SMC) achieves robustness to parameter variations and disturbances by:','{"choices": ["Using high-gain linear feedback", "Switching the control input at high frequency to force the system state trajectory onto a sliding surface — on the surface, dynamics are governed by the surface equation (independent of matched disturbances)", "Using a lookup table for all possible states", "Requiring exact system model knowledge"], "correct": 1}'::jsonb,'SMC: design a sliding surface s(x)=0 with desired reduced-order dynamics. Control law: u = u_eq − K×sign(s). When on the surface, system is in "sliding mode" — robust to matched uncertainties and disturbances. Drawback: chattering from high-frequency switching; mitigated with boundary layer (saturation instead of sign).','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-19','Frequency Domain: Gain and Phase Crossover','Hard','EEE','arena','interpret','Control Systems','multiple_choice','A control system has gain margin GM = 12 dB and phase margin PM = 55°. This indicates:','{"choices": ["System is unstable", "System is marginally stable", "System is stable with good robustness — GM > 6 dB and PM > 45° are typical design targets; this system can tolerate significant gain variations and phase lag before becoming unstable", "System will oscillate continuously"], "correct": 2}'::jsonb,'GM = 12 dB: gain can increase by 12 dB (factor 4) before instability. PM = 55°: additional 55° of phase lag can be tolerated. Good design targets: GM > 6 dB (2×), PM > 45°. Automobile industry often targets PM > 30°, GM > 6 dB. Aerospace: PM > 45°.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-20','Second-Order System: Damping Ratio','Hard','EEE','arena','calculate','Control Systems','multiple_choice','A second-order closed-loop system has characteristic equation: s² + 2s + 4 = 0. The damping ratio ζ and natural frequency ωₙ are:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-21','Feedforward Control','Hard','EEE','arena','select','Control Systems','multiple_choice','Feedforward control is combined with feedback control to:','{"choices": ["Replace the need for sensors", "Reject measurable disturbances before they affect the output — by measuring the disturbance and applying a compensating input, feedforward acts instantaneously without waiting for error to develop", "Stabilise an unstable plant", "Reduce steady-state error to zero"], "correct": 1}'::jsonb,'Feedforward: if disturbance d is measurable, apply u_ff = −G_d/G_p × d to cancel it. Perfect disturbance rejection without waiting for feedback. Requires accurate process model. Combined: feedback corrects model errors and unmeasured disturbances; feedforward handles measured disturbances.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-22','Internal Model Principle','Hard','EEE','arena','interpret','Control Systems','multiple_choice','The Internal Model Principle states that for zero steady-state tracking error to a class of reference signals, the controller must contain a model of:','{"choices": ["The plant dynamics", "The reference signal generator — e.g., for zero steady-state error to a ramp, the controller must include an integrator (1/s); for a sinusoidal reference at ω₀, the controller must include the resonant mode s²+ω₀²", "The measurement noise", "The closed-loop transfer function"], "correct": 1}'::jsonb,'IMP (Francis-Wonham theorem): for robust zero tracking error, the controller or loop must contain an internal model of the disturbance/reference signal generator. PI controller contains 1/s → tracks step references. Repetitive controller contains e^{sT}/1−e^{sT} → tracks periodic signals.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-23','Anti-Windup: Back-Calculation','Hard','EEE','arena','select','Control Systems','multiple_choice','Back-calculation anti-windup in a PID controller works by:','{"choices": ["Clamping the integral term to zero when error is zero", "Feeding back the difference between actuator output and controller output (saturation error) through a gain T_t to the integrator, reducing its value when the actuator saturates", "Disabling the integral when output reaches setpoint", "Increasing derivative gain to counteract windup"], "correct": 1}'::jsonb,'Back-calculation: when actuator saturates (u_actual ≠ u_desired), the difference (u_actual − u_desired) is fed back to the integrator input through 1/T_t. This drives the integrator to the correct value that would produce u_actual, ready for when saturation ends.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-24','Stability: Lyapunov Method','Hard','EEE','arena','interpret','Control Systems','multiple_choice','Lyapunov''s direct method proves stability of a nonlinear system by:','{"choices": ["Solving the nonlinear differential equations", "Finding a scalar function V(x) (energy-like) that is positive definite and whose time derivative along trajectories is negative semi-definite — if V̇ < 0, the system asymptotically converges to equilibrium", "Linearising around the operating point", "Computing eigenvalues of the Jacobian matrix"], "correct": 1}'::jsonb,'Lyapunov function V(x): V(0)=0, V(x)>0 for x≠0. If V̇(x)≤0 → stable. If V̇(x)<0 → asymptotically stable. Difficulty: finding V for complex nonlinear systems. Common candidates: quadratic V = x^T P x (SDP-based LMI methods find P automatically).','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-co-25','Digital Control: Zero-Order Hold','Hard','EEE','arena','interpret','Control Systems','multiple_choice','A zero-order hold (ZOH) in a digital control system adds phase lag proportional to the sampling period T_s. The equivalent phase lag at frequency ω is approximately:','{"choices": ["T_s × ω radians", "ωT_s/2 radians", "2ωT_s radians", "ωT_s radians"], "correct": 1}'::jsonb,'ZOH equivalent delay: approximately T_s/2 (half a sample period). Phase lag = ω × T_s/2. For f_s = 1 kHz, T_s = 1 ms: at bandwidth ω = 100 rad/s, phase lag = 100 × 0.0005 = 0.05 rad ≈ 2.9°. Rule of thumb: sample at 10–20× control bandwidth.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
